(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["haw"] = {"ui":{"skip":"E lele i ka ʻike","back":"← E hoʻi i AI-gile","lang.button":"ʻŌlelo: {name}","lang.dialog":"E koho i kahi ʻōlelo","lang.search":"E ʻimi i nā ʻōlelo","lang.none":"ʻAʻohe ʻōlelo kūpono","lang.notYet":"ʻAʻole i unuhi ʻia ka {name}","theme.aria":"E hoʻololi ma waena o ke ʻano ʻālohilohi a me ke ʻano ʻeleʻele","theme.toLight":"E hoʻololi i ke ʻano ʻālohilohi","theme.toDark":"E hoʻololi i ke ʻano ʻeleʻele","index.title":"AI-gile: kāu pūʻulu hoʻomohala AI, ma hoʻokahi papa","index.description":"He papa kanban ʻo AI-gile no nā pūʻulu hoʻopaʻa code AI. Ke hana nei lākou i kou hiamoe ʻana; loaʻa iā ʻoe kekahi puʻu pōkole o nā mea e hoʻoholo ai, e hoʻāʻo ai a e ʻae ai.","hero.logoAlt":"Hōʻailona papa AI-gile","hero.h1.html":"Kāu pūʻulu hoʻomohala AI, ma hoʻokahi&nbsp;papa.","hero.alpha":"🐣 Pre-alpha pani ʻia","hero.alphaTitle":"Ma ka hoʻomaka a ʻaʻole i pau: mahalo no ka hoʻāʻo ʻana!","hero.lede":"Hana lākou i kou hiamoe ʻana. Ala ʻoe i kekahi puʻu pōkole: kekahi mau nīnau, kekahi mau mea e hoʻāʻo ai, hoʻokahi a ʻelua paha daimana poni. E kaomi, e ʻae, a e hoʻi i kāu kope.","dl.windows":"ʻApp Windows","dl.browser":"E holo ma kāu polokalamu kele","dl.soon":"E hiki mai ana","dl.notify":"🔔 E haʻi mai iaʻu ke wehe ʻia","dl.notifySmall":"Alpha a i ʻole beta","hero.secondary":"Agile, akā ʻaʻole pono i ka pūʻulu ke kope kū o ka hālāwai. (Hālāwai nō naʻe lākou.)","pitch.h2":"AI-gile i nā huaʻōlelo he nui a he liʻiliʻi e like me kāu makemake","pitch.lede":"E koho i ka lōʻihi, mai ka huaʻōlelo hoʻokahi a i 144. He wehewehe ponoʻī kēlā me kēia lōʻihi, i kākau ʻia no ia nui. E huki i ka ʻōwili a i ʻole e hoʻohana i nā pihi pua.","pitch.rangeLabel":"Ka lōʻihi ma nā huaʻōlelo","pitch.dice":"🎲 kekahi mana ʻē aʻe","pitch.words.one":"{n} huaʻōlelo","pitch.words.other":"{n} huaʻōlelo","pitch.letters.one":"{n} leka","pitch.letters.other":"{n} leka","pitch.chars.one":"{n} hōʻailona","pitch.chars.other":"{n} hōʻailona","count.line.html.one":"{n} kāleka ma ka papa i kēia manawa","count.line.html.other":"{n} kāleka ma ka papa i kēia manawa","features.aria":"Ka mea āna e hana ai","f.pile.h":"Hoʻokahi puʻu no ʻoe","f.pile.html":"Mālama ʻo <b>No ʻoe</b> i nā mea a pau e kali nei iā ʻoe, ma nā papahana a pau: nā nīnau, nā mea e hoʻāʻo ai, nā hana hiki i ke kanaka wale nō. Ua ʻōlelo kāu laina i ka mea aʻe a me ka lōʻihi o ka manawa.","f.sleep.h":"Nā pūʻulu hana i kou hiamoe ʻana","f.sleep.p":"He alakaʻi a he pūʻulu mea hana AI kā kēlā me kēia papahana. E ʻōlelo ma kekahi kāleka a ala ka pūʻulu, hana i ka hana, a hoʻihoʻi me nā ʻanuʻu hiki i ke kanaka luhi ke hahai.","f.tester.h":"Nānā mua ka mea hoʻāʻo AI","f.tester.p":"Ma mua o ka hiki ʻana mai o kekahi mea iā ʻoe, hahai ka mea hoʻāʻo i nā ʻanuʻu ma kahi kope o ka ʻapp a hōʻike i kāna i ʻike ai, me ke kiʻi pale. E nānā wikiwiki i ka mea i pono a e ʻae me ke kaomi hoʻokahi.","f.proof.h":"He hōʻike, ʻaʻole he hoʻohiki","f.proof.p":"Hōʻike kēlā me kēia hāʻawi i ka mea i loli: nā waihona, ka ʻokoʻa, nā kiʻi pale. ʻAʻole pono e wehe i kēlā me kēia ʻapp e ʻike ai ua pau.","f.chat.h":"E kamaʻilio me kou mau alakaʻi","f.chat.p":"He alahaka e like me Discord: hoʻokahi hōʻailona no kēlā me kēia papahana, nā daimana poni no ka mea e makemake ana iā ʻoe. E hoʻouna i kahi manaʻo i ka alakaʻi; hoʻololi ʻo ia i mau kāleka a me ka manaʻo hana, me ke pihi ✅ Go.","f.tidy.h":"Mālama i ia iho","f.tidy.p":"Hui nā kāleka pili i hoʻokahi, hoʻoponopono ʻia nā poʻo inoa pohihihi, a mālama ka nānā token i ke code i māmā. ʻOi aku ka liʻiliʻi o nā mea e hoʻololi ai, ka liʻiliʻi o ka noʻonoʻo.","f.private.h":"Nou, ma kāu kamepiula","f.private.li1":"Holo ka papa ma kāu mīkini ponoʻī a pane iā ʻoe wale nō.","f.private.li2":"Ua hūnā ʻia nā DM pilikino ma waena o nā kānaka mai ke kiko a i ke kiko.","f.private.li3":"ʻAʻohe moʻokāki, ʻaʻohe mea alualu, ʻaʻohe kuki.","f.lang.h":"Ma kāu ʻōlelo","f.lang.p":"Ma luna o 120 ʻōlelo, mai ka Holani, ka Wales a me ka Kepani a hiki i ka ʻōlelo pailaka, ʻo Yoda a me Klingon, me ka hoʻololi wikiwiki i ka Pelekānia no nā huaʻōlelo mea hoʻomohala.","tl.aria":"Laina manawa mai ka kamaʻilio mua a hiki i ke ala e hiki mai ana","tl.h2":"Mai ka kamaʻilio mua a i ka mea e hiki mai ana","tl.lede":"Nā lā a me nā manawa maoli, ma kou wā ponoʻī. Ma hope o kēia lā he hoʻolālā ia, ʻaʻohe lā i hoʻohiki ʻia.","tl.today":"Kēia lā","tl.planned":"hoʻolālā ʻia","tl.cards.one":"{n} kāleka","tl.cards.other":"{n} kāleka","join.h2":"E komo mai","join.lede":"Ke kūkulu ʻia nei ʻo AI-gile e ke kanaka liʻiliʻi a me nā mea hana ʻoli he nui. He pilikino ia i kēia manawa, ma ka alpha pani ʻia me nā hoaaloha. Makemake ʻoe e hoʻāʻo ke wehe ʻia?","join.btn":"E kākau i kou hoihoi","join.small":"E leka uila aku mākou iā ʻoe, ʻaʻohe mea ʻē aʻe","footer.tag":"AI-gile. ʻAʻohe mea alualu, ʻaʻohe kuki, ʻaʻohe kope kū hālāwai.","footer.licence":"ʻAe ʻoihana","footer.status":"Kūlana","form.sending":"Ke hoʻouna nei…","form.failed":"ʻAʻole i hana kēlā: e hoʻāʻo hou ma hope.","form.offline":"ʻAʻole hiki ke hōʻea iā AI-gile: e hoʻāʻo hou ma hope.","interest.title":"AI-gile: e haʻi mai iaʻu ke wehe ʻia ka alpha","interest.description":"E waiho i kāu leka uila e lohe ai i ka wā e wehe ai ka alpha a i ʻole ka beta pani ʻia o AI-gile.","interest.h1":"🔔 E haʻi mai iaʻu ke wehe ʻia","interest.lede":"Ma ka pre-alpha pani ʻia ʻo AI-gile. E waiho i kāu leka uila a e kākau aku mākou hoʻokahi manawa, ke loaʻa kahi wahi nou.","interest.email":"Kāu leka uila","interest.which":"ʻO ka hoʻāʻo ʻehea?","interest.alpha":"Alpha pani ʻia: mua, ʻōhūhū, nui nā loli","interest.beta":"Beta: ʻoi aku ka paʻa, ma hope","interest.both":"ʻO kekahi paha, ka mea e hiki mua mai","interest.submit":"E hoʻokomo iaʻu i ka papa inoa","interest.thanks":"Mahalo! Aia ʻoe ma ka papa inoa.","interest.kept":"ʻO kāu leka uila wale nō a me ka hoʻāʻo āu i koho ai ka mea mālama ʻia, no kēia papa inoa wale nō. ʻAʻohe nūhou leka, ʻaʻohe mea alualu.","licence.title":"AI-gile: ʻae ʻoihana","licence.description":"Hoʻohana ʻoe iā AI-gile ma kāu ʻoihana? E noi i ka ʻae ʻoihana manuahi.","licence.h1":"📜 ʻAe ʻoihana","licence.lede":"Hoʻohana ʻoe iā AI-gile ma ka hana? E haʻi mai ʻo wai ʻoe a he aha kāu e hana nei. Inā he pono kāna hana, manuahi ka ʻae.","licence.company":"Hui","licence.website":"Pūnaewele","licence.what":"Kāu hana","licence.how":"Pehea ia e kōkua ai i ka honua","licence.email":"Leka uila","licence.submit":"E noi","licence.thanks":"Mahalo! E pane aku mākou ma ka leka uila.","status.title":"Kūlana AI-gile","status.h1":"Kūlana AI-gile","status.quiet":"Mālie nō","status.checking":"Ke nānā nei…","status.offline":"ʻAʻole hiki ke hōʻea i ka lawelawe kūlana i kēia manawa (ke hoʻāʻo hou nei)","status.updated":"ua hōʻano hou ʻia {ago}","status.justNow":"i kēia manawa wale nō","status.min":"{n} minuke i hala","status.hours":"{n} hola i hala","status.days":"{n} lā i hala"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Hāʻawi."]},{"n":2,"texts":["Kanban robot.","Robot ʻoli.","Manaʻo, kūkulu."]},{"n":3,"texts":["Kanban no nā robot.","Lilo ka manaʻo hiʻona.","Kanban mea hana manuahi."]},{"n":5,"texts":["Papa kanban a nā mea hana.","Kākau kāleka. Kūkulu nā mea hana.","Manuahi, kūloko, hoʻāʻo ʻia, lealea iki."]},{"n":8,"texts":["Papa kanban manuahi, hana nā mea hana AI.","Kākau i manaʻo. Kūkulu nā mea hana. ʻAe ʻoe.","Agile no ke kanaka a me nā robot ʻoli."]},{"n":13,"texts":["Papa kanban ma kāu kamepiula, lawe nā mea hana AI i nā kāleka.","E kākau i kahi manaʻo. Kūkulu kekahi pūʻulu mea hana iā ia. Nānā ka mea hoʻāʻo.","Manuahi, ʻaʻohe moʻokāki a mea alualu: he papa, kekahi mau robot, a ʻo ʻoe ka luna."]},{"n":21,"texts":["He papa kanban ʻo AI-gile no ka hana pū me nā mea hana hoʻopaʻa code AI. Lawe lākou i nā kāleka; hoʻāʻo ʻoe a ʻae.","Loaʻa i ka papahana kēlā me kēia kahi alakaʻi a me pūʻulu mea hana AI. ʻŌlelo ma kekahi kāleka, hoʻomaka ka pūʻulu.","He papa hana pilikino manuahi e holo ana ma kāu kamepiula ponoʻī. He mau robot nā limahana. ʻO ʻoe ka mea e ʻōlelo ana ʻae."]},{"n":34,"texts":["Waiho ʻoe i nā manaʻo ma ka papa. Hoʻololi kekahi pūʻulu mea hana AI iā lākou i mau hiʻona hana, hoʻāʻo, a hoʻihoʻi me nā ʻanuʻu. ʻAʻohe mea i pau a ʻōlelo ʻoe.","He papa kanban hale ʻo AI-gile a Rich i kūkulu ai me ke kōkua o nā mea hana āna e alakaʻi nei. Manuahi, holo ma kāu kamepiula, kaʻana like me nā hoaaloha, ʻaʻole kūʻai.","E noʻonoʻo i kahi papa kanban maʻamau, me nā kolamu mai Backlog a Pau, akā lawe nā mea hana AI i nā kāleka. Hōʻike lākou i ka holomua, nīnau ke paʻa, a kali mau i kou ʻae ʻana."]},{"n":55,"texts":["He papa kanban ʻo AI-gile a he mau mea hana AI ka pūʻulu. He alakaʻi kā kēlā me kēia papahana nāna e hoʻolālā, a he mau kōkua nāna e kūkulu. Ke mākaukau kekahi hiʻona, hoʻāʻo ka mea hoʻāʻo AI a lawe i kiʻi pale, a hiki i kāu puʻu. E ʻae, a i ʻole e ʻōlelo a hana hou lākou.","Hoʻomaka ia ma ke ʻano he ala o hoʻokahi kanaka e mālama i nā hālāwai hoʻopaʻa code AI he nui i ka manawa hoʻokahi, a ulu ia i papa kūpono. Holo ia ma kāu mīkini, ʻaʻole noi i moʻokāki, a ʻaʻohe mea alualu. ʻAʻole naʻe i pau, no laila e manaʻo i nā ʻaoʻao ʻōhūhū a me kekahi mea e kāhāhā ai.","Eia ka mana ʻoiaʻiʻo. Pono nō ʻoe e loaʻa nā manaʻo a nānā i nā hopena. Hana ʻo AI-gile i nā mea ma waena: mālama i nā kāleka, hoʻāla i ka mea hana kūpono ke ʻōlelo ʻoe, hōʻike i ka mea i loli, a hōʻuluʻulu i hoʻokahi puʻu pōkole nou."]},{"n":89,"texts":["He papa kanban manuahi ʻo AI-gile e holo ana ma kāu kamepiula. Loaʻa i kēlā me kēia papahana kahi pūʻulu mea hana AI: he alakaʻi nāna e hoʻololi i kou mau manaʻo i kāleka a me hoʻolālā, a he mau kōkua nāna e lawe i nā kāleka. Ke kūkulu ʻia kekahi mea, hahai ka mea hoʻāʻo AI i nā ʻanuʻu a hōʻike i kāna i ʻike ai. A laila kali ia ma kahi puʻu i kapa ʻia No ʻoe. ʻAe ʻoe, a i ʻole ʻōlelo a hoʻāʻo hou ka pūʻulu. ʻAʻohe mea e hiki i Pau me ʻoe ʻole.","Aia kekahi mau hiʻona āu e manaʻo ʻole ai. Mālama ke kiaʻi pō i ke kolamu Hana i piha i kou hiamoe ʻana, me nā kāleka ʻaʻole pono i kāu pane. Hōʻike ka helu token i ka hoʻohana o kēia lā a me kēia pule, a ʻōlelo ke ʻano ʻAʻohe Hōʻailona e hoʻōki. Hiki iā ʻoe ke hoʻouna i nā leka i nā hoaaloha, hūnā ʻia mai ke kiko a i ke kiko. Kamaʻilio ka papa i kahi o 120 ʻōlelo, me ka Holani, ka pailaka a me Klingon. ʻAʻohe kumukūʻai, a ʻaʻohe mea e hoʻāʻo nei e kūʻai aku iā ʻoe.","He papahana liʻiliʻi pilikino ʻo AI-gile, ʻaʻole he hui. Makemake ʻo Rich e mālama i nā papahana hoʻopaʻa code AI he nui me ka wehe ʻole i kēlā me kēia ʻapp e nānā ai, no laila kūkulu ʻo ia a me nā mea hana i papa no ia, a laila hoʻohana i ka papa e kūkulu i ke koena. Aia ia ma ka pre-alpha pani ʻia, ʻo ia hoʻi, hana ia, ʻo ka hapa nui, no kekahi mau hoaaloha. ʻAʻohe ʻaoʻao kumukūʻai, ʻaʻohe nūhou leka, a ʻaʻohe hoʻolālā ulu. Inā ʻike ʻia he kōkua, hiki iā ʻoe ke noi e hoʻāʻo ke wehe ākea iki ʻia."]},{"n":144,"texts":["He papa kanban ʻo AI-gile no hoʻokahi kanaka a me nā mea hana AI he nui. Holo ia ma kāu kamepiula a manuahi loa. Hoʻohui ʻoe i nā papahana, a loaʻa i kēlā me kēia kahi alakaʻi a me kahi pūʻulu liʻiliʻi. Kamaʻilio ʻoe me ka alakaʻi, e like me Discord, a wehewehe i kahi manaʻo; hoʻololi ia i mau kāleka a me kahi hoʻolālā, a kali e kaomi ʻoe i Go. Hana ka pūʻulu ma nā kāleka ma ke ʻano koʻikoʻi, me kahi laina kauoha maʻalahi no nā kumu hoʻohālike ʻōlelo. Ma mua o ka hoʻi ʻana mai, hahai ka mea hoʻāʻo AI i nā ʻanuʻu ma kahi kope o ka ʻapp a hoʻohui i kiʻi pale. Hiki ka hana i pau i kāu puʻu me nā waihona i loli a me ka ʻokoʻa. ʻAe ʻoe, a i ʻole ʻōlelo ʻoe a hoʻāʻo hou ka pūʻulu. ʻO ʻoe wale nō hiki ke hoʻoneʻe i kāleka i Pau.","He lā me AI-gile, ma kahi o ia. I ke ahiahi waiho ʻoe i kekahi mau ʻōlelo: aia kēia pihi ma ka wahi hewa, pono e hoʻokaʻina ʻia kēlā papa inoa, hiki paha iā mākou ke loaʻa i ke ʻano ʻeleʻele. Hiamoe ʻoe. Heluhelu nā mea hana i nā ʻōlelo, hana i nā loli, hoʻāʻo iā lākou a hoʻihoʻi iā ʻoe. Inā hakahaka ka Hana, hoʻopiha ke kiaʻi pō iā ia mai ka backlog me nā kāleka ʻaʻole pono i kāu pane. I ke kakahiaka he hoʻokahi puʻu pōkole: ʻelua nīnau a me kekahi mau mea e hoʻāʻo ai, me nā ʻanuʻu hiki i ke kanaka hiamoe ke hahai a me kahi kiʻi pale e hana ana. Kaomi ʻoe, ʻae i ka maikaʻi a hoʻihoʻi i ke koena. Hōʻike ka helu token i ka mea i hoʻohana ʻia, a aia ke ʻano ʻAʻohe Hōʻailona no nā pule liʻiliʻi. A laila ʻai ʻoe i ka ʻaina kakahiaka, ʻaʻole hiki i nā mea hana ke kōkua.","ʻO ka mea mua, ka mea ʻaʻole ʻo AI-gile. ʻAʻole he hoʻomaka hui, ʻaʻole kūʻai ʻia, a ʻaʻohe mea e hōʻuluʻulu ana i kāu ʻikepili. He papa manuahi ia e holo ana ma kāu kamepiula, me ka moʻokāki ʻole, mea alualu ʻole a kuki ʻole. He wahi maikaʻi ia e ʻike ai i nā papahana hoʻopaʻa code AI a pau i ka manawa hoʻokahi, me kahi pūʻulu mea hana e hana ana i nā kāleka a ʻo ʻoe ka mea hoʻoholo. Hoʻohui ia i nā kāleka pili, hoʻoponopono i nā poʻo inoa pohihihi, a nānā i ka māmā o ke code. Kamaʻilio ia ma kahi o 120 ʻōlelo, mai ka Holani a i ka pailaka a me Klingon. Kūkulu ʻia e Rich a me nā mea hana ʻoli he nui. Aia ia ma ka pre-alpha pani ʻia, no laila ʻōhūhū ma kekahi mau wahi. Inā leʻaleʻa ia iā ʻoe, e noi me ke ahonui."]}],"quips":{"1":"Hoʻokahi huaʻōlelo. Wiwoʻole. Wiwoʻole loa paha.","3":"ʻEkolu huaʻōlelo. ʻOi aku ka pololei ma mua o ka hapa nui o nā ʻaoʻao huahana.","8":"ʻEwalu huaʻōlelo. Poto ma mua o ka hālāwai kū.","21":"He kiko moʻolelo nā lōʻihi, ma ke ala. ʻIo nō.","55":"Kanalimakūmālima huaʻōlelo. Pau ʻelua kāleka i kou heluhelu ʻana i kēia.","144":"ʻO ia ka mea lōʻihi. ʻAʻohe 233. Ua hele nā mea hana e hiamoe."}},"timeline":{"first-idea.name":"Ka manaʻo mua","first-idea.line":"Ka kamaʻilio mua loa, ma mua o ka loaʻa ʻana o kekahi code.","first-board.name":"Ka papa mua","first-board.line":"He papa e nānā ana i kona kūkulu ponoʻī: nā kāleka, nā kolamu, huki a kau, nā papahana.","team-roles.name":"Pūʻulu a me nā kuleana","team-roles.line":"Nā ʻano mea hana, nā kumu hoʻohālike pūʻulu, nā wahi a me ka mea nāna e hana i ka aha.","install.name":"Kau a me nā hoʻokuʻu","install.line":"He zip hiki i ke hoaaloha ke kau, hōʻano hou ponoʻī, nā kahawai a me ka hoʻi.","usage-saver.name":"Mālama hoʻohana","usage-saver.line":"E ana i ke kumukūʻai o nā holo, mālama i ke code i māmā, mālama i kou palena.","friends.name":"Nā hoaaloha a me ke kaʻana like","friends.line":"Nā DM pilikino, he relay hūnā ʻia, nā kono, nā kuleana a me nā papahana i kaʻana like ʻia.","languages.name":"Nā ʻōlelo","languages.line":"Kēlā me kēia kikokikona pale ma kahi waihona ʻōlelo, me ka Holani a me ka Flemish ma mua.","ai-tester.name":"Mea hoʻāʻo AI","ai-tester.line":"Nānā ka mea hoʻāʻo i kēlā me kēia hāʻawi ma mua a hōʻike i kāna i ʻike ai.","website.name":"Ka pūnaewele","website.line":"aigile.lol, ka teaser a me kēia laina manawa.","streaming.name":"Kamaʻilio a me ka kahe","streaming.line":"Discord, Twitch, OBS, ke ʻano kahe, GIF a me emoji.","no-ai.name":"Mana AI ʻole","no-ai.line":"He papa no ka poʻe hoʻopaʻa code me ka AI ʻole, a me nā papa lehulehu.","night-watch.name":"Kiaʻi pō","night-watch.line":"Mālama ke kiaʻi a me ka Scrum Master i nā pūʻulu ma ka hana i kou hiamoe ʻana.","p-more.name":"Nā mea ʻē aʻe a pau","p-more.line":"Nā manaʻo liʻiliʻi e kali ana i ko lākou wā.","p-android.name":"Kelepona a me Android","p-android.line":"E hōʻea i kāu papa mai kahi kelepona, a laila he ʻapp Android maoli.","p-release.name":"Alpha a ma hope aku","p-release.line":"Alpha pani ʻia, ka pūnaewele ola, a laila beta.","p-languages.name":"Nā ʻōlelo hou aʻe","p-languages.line":"Ma luna o hoʻokahi haneli ʻōlelo, a me ke ʻano hoʻokomo piha no ka poʻe aʻo.","p-engines.name":"Nā ʻenekini AI hou aʻe","p-engines.line":"E koho iā Claude, Codex a i ʻole Gemini no kēlā me kēia mea hana.","p-pro.name":"Hana loea","p-pro.line":"Nā lepili pilikia, nā puka hoʻohui, nā kāleka hanana a me nā pale.","p-self.name":"Ka mālama ʻana iā ʻoe","p-self.line":"Ke ʻano luhi, nā hoʻomanaʻo mālama iā ʻoe iho a me 4:20.","p-servers.name":"Nā kikowaena a me ka nui","p-servers.line":"Nā hoʻonohonoho kikowaena āpau, nā kuleana a me ka hoʻolālā ulu.","p-livestream.name":"Nā mea hou o ka kahe","p-livestream.line":"Ke kamaʻilio Twitch, nā emoji ponoʻī a me kahi nānā ola lehulehu."}};
